{"source":"def build_prompt(context):
    parents = context.get('parent_ids', [])
    evidence = context.get('evidence_ids', [])
    slot = context.get('slot', 0)
    round_no = context.get('round', 0)
    candidates = context.get('candidates', {})
    ranked = []
    for i in range(len(parents)):
        pid = parents[i]
        rec = candidates.get(pid, {})
        score = rec.get('training_score', rec.get('score', 999999999))
        if score == None:
            score = 999999999
        ranked.append([score, pid])
    for i in range(len(ranked)):
        for j in range(i + 1, len(ranked)):
            if ranked[j][0] < ranked[i][0]:
                tmp = ranked[i]
                ranked[i] = ranked[j]
                ranked[j] = tmp
    ev = []
    for name in ['native', 'bootstrap/initial-incumbent']:
        for e in evidence:
            if e == name and e not in ev:
                ev.append(e)
    for e in evidence:
        if e not in ev:
            ev.append(e)
    if len(ev) > 4:
        ev = ev[:4]
    op = 'construct'
    chosen = []
    rule = 0
    if len(parents) > 0 and len(ranked) > 0:
        best = ranked[0][1]
        if slot % 3 == 2 and len(ranked) > 1:
            op = 'crossover'
            chosen = [ranked[0][1], ranked[1][1]]
            rule = 2
        elif slot % 3 == 1 or round_no > 0:
            op = 'mutate'
            chosen = [best]
            rule = 3
        else:
            op = 'construct'
            chosen = []
            rule = 0
    if op == 'construct':
        guidance = 'Construct from native-first training evidence: use topology-aware owner placement with a bounded local fallback; retain producer copies only for hot blocks; add allocation/eviction and reclaim fallbacks so long_document_qa pressure does not scan every victim.'
    elif op == 'crossover':
        guidance = 'Crossover the two best-scored archived parents: keep the lower-pressure placement/reclaim structure from the better parent and the explicit eviction/replicate guards from the other; validate on long_document_qa allocation pressure and asymmetric host links.'
    else:
        guidance = 'Mutate rule index ' + str(rule) + ' of the best-scored parent: replace broad allocation/eviction scans with a reuse-aware victim choice, preserve native-style demand/replica simplicity, and keep a reclaim fallback for zero-reference blocks.'
    return str({'operator': op, 'parents': chosen, 'evidence': ev, 'rule': rule, 'guidance': guidance})

def build_meta_prompt(context):
    evidence = context.get('evidence_ids', [])
    round_no = context.get('round', 0)
    ev = []
    for name in ['native', 'bootstrap/initial-incumbent']:
        for e in evidence:
            if e == name and e not in ev:
                ev.append(e)
    for e in evidence:
        if e not in ev:
            ev.append(e)
    if len(ev) > 4:
        ev = ev[:4]
    mode = 'repair'
    if round_no > 1:
        mode = 'rethink'
    guidance = 'Repair the incumbent using native as the lower-scored training control: preserve the simpler placement/demand/eviction shape, then specialize allocation eviction for long_document_qa and asymmetric host links; keep reclamation as a mandatory fallback and reject only changes that lose the matched-archive comparison.'
    return str({'mode': mode, 'evidence': ev, 'guidance': guidance})","plan":{"observed_problem":"In the supplied training evidence the structured incumbent scored 310.222912 ms versus native 289.156337 ms on sum_case_median_ms, lower is better. The gap is concentrated in long_document_qa: 1175 allocate/evict indexed choices, 18715 rows scanned, 157 fetch misses, 19.8878 ms median transfer and 163.812788 ms median elapsed; host0 peak is 37093376 B against 524288 B GPU capacity while gpu0-host0 carries 41877504 B. The parent generator ignores candidate scores and always uses rule 0 with first evidence order, so it cannot target this allocation/eviction pressure.","mechanism_change":"build_prompt now ranks parent_ids by candidates training_score or score, orders evidence native-first, keeps slot0 construct, uses mutate on slot1 and later with the best parent and rule index 3 to target allocation/eviction, and uses crossover of the two best parents at slot2 when available. build_meta_prompt changes from revise to repair or rethink and uses native-first evidence, so both ASTs and selected meta evidence or mode change.","expected_effect":"Hypothesis: native-first evidence plus score-ranked parents and rule-3 mutation will produce a distinct selected task decision that preserves native simpler placement and reclaim shape while reducing long_document_qa allocation/eviction scan work, fetch misses and transfer time, lowering sum_case_median_ms versus both the parent and the incumbent on the matched training archive.","falsification":"Falsified if the gate finds the task decision unchanged in operator, parents, evidence or rule, or the meta decision unchanged in mode or evidence, or if the selected output matched-archive sum_case_median_ms is not lower than both parent and incumbent, especially with no reduction in long_document_qa allocate/evict rows_scanned or fetch_misses."}}
